/* From Uiverse.io by PriyanshuGupta28 - Tags: checkbox, docs checkbox, checkmark */
.__UIV_SCOPE__ .checkbox-wrapper input[type="checkbox"] {
  display: none;
}

.__UIV_SCOPE__ .checkbox-wrapper .terms-label {
  cursor: pointer;
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .checkbox-wrapper .terms-label .label-text {
  margin-left: 10px;
}

.__UIV_SCOPE__ .checkbox-wrapper .checkbox-svg {
  width: 30px;
  height: 30px;
}

.__UIV_SCOPE__ .checkbox-wrapper .checkbox-box {
  fill: rgba(207, 205, 205, 0.425);
  stroke: #8c00ff;
  stroke-dasharray: 800;
  stroke-dashoffset: 800;
  transition: stroke-dashoffset 0.6s ease-in;
}

.__UIV_SCOPE__ .checkbox-wrapper .checkbox-tick {
  stroke: #8c00ff;
  stroke-dasharray: 172;
  stroke-dashoffset: 172;
  transition: stroke-dashoffset 0.6s ease-in;
}

.__UIV_SCOPE__ .checkbox-wrapper input[type="checkbox"]:checked + .terms-label .checkbox-box,
  .__UIV_SCOPE__ .checkbox-wrapper input[type="checkbox"]:checked + .terms-label .checkbox-tick {
  stroke-dashoffset: 0;
}
